package store

// Fixed runtime SQL allowlist, bounded independently of users and traffic.
// Unlisted SQL uses the ordinary transaction path. Keeping the original SQL
// at each call site makes its guards and mutations directly reviewable.
var runtimeQueries = [...]string{
	`SELECT COUNT(*) FROM unknown_usage_batches WHERE node_id=? AND batch_id=?`,
	`INSERT INTO usage_reservations(node_id,boot_id,batch_id,snapshot_id,flow_key,rule_id,direction,reserved_bytes,state,used_bytes,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)`,
	`SELECT MAX(second) FROM demand_consumption WHERE scope=?`,
	`SELECT second,bytes FROM demand_consumption WHERE scope=? AND slot=?`,
	`INSERT INTO demand_consumption(scope,slot,second,bytes) VALUES(?,?,?,?) ON CONFLICT(scope,slot) DO UPDATE SET second=excluded.second,bytes=excluded.bytes`,
	`SELECT snapshot_id,payload_sha256 FROM settled_usage_tombstones WHERE node_id=? AND batch_id=?`,
	`SELECT boot_id, snapshot_id, payload, payload_sha256, unknown_upper_bound, state, created_at FROM usage_batches WHERE node_id=? AND batch_id=?`,
	`SELECT payload_sha256 FROM usage_batches WHERE node_id=? AND batch_id=? UNION ALL SELECT payload_sha256 FROM unknown_usage_batches WHERE node_id=? AND batch_id=?`,
	`SELECT report_boot_id,sequence,payload_sha256 FROM usage_origin_envelopes WHERE node_id=? AND batch_id=?`,
	`INSERT INTO usage_origin_envelopes(node_id,batch_id,report_boot_id,sequence,payload_sha256) VALUES(?,?,?,?,?)`,
	`SELECT payload_sha256 FROM settled_usage_tombstones WHERE node_id=? AND batch_id=?`,
	`SELECT payload,payload_sha256 FROM usage_batches WHERE node_id=? AND batch_id=?`,
	`INSERT INTO usage_backend_receipts(node_id,batch_id,kind,payload_sha256,confirmed_at) VALUES(?,?,?,?,?) ON CONFLICT DO NOTHING`,
	`SELECT kind,payload_sha256 FROM usage_backend_receipts WHERE node_id=? AND batch_id=?`,
	authorizationRecordQuery,
	`SELECT epoch FROM runtime_rate_clock_epochs WHERE node_id=? AND source_id=?`,
	`INSERT INTO runtime_rate_clock_epochs(node_id,source_id,epoch) VALUES(?,?,?) ON CONFLICT(node_id,source_id) DO UPDATE SET epoch=excluded.epoch`,
	`SELECT boot_id,grant_id,runtime_lease_id,share_lease_id,state FROM runtime_sessions WHERE node_id=? AND session_id=?`,
	`SELECT authorization_id,reserved_bytes,state FROM authorization_usage_holds WHERE node_id=? AND batch_id=?`,
	`SELECT 1 FROM runtime_funding_blocks WHERE node_id=? AND batch_id=?`,
	`SELECT boot_id,snapshot_id,flow_key,rule_id,direction,reserved_bytes,state FROM usage_reservations WHERE node_id=? AND batch_id=?`,
	`SELECT source_id,remaining_bytes FROM authorization_balances WHERE node_id=? AND authorization_id=?`,
	`UPDATE authorization_balances SET remaining_bytes=?,updated_at=? WHERE node_id=? AND authorization_id=? AND source_id=?`,
	`INSERT INTO authorization_usage_holds(node_id,batch_id,authorization_id,source_id,reserved_bytes,state) VALUES(?,?,?,?,?,?)`,
	`INSERT INTO usage_reservations(node_id,boot_id,batch_id,snapshot_id,flow_key,rule_id,direction,reserved_bytes,state,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)`,
	`SELECT initial_bytes,remaining_bytes FROM authorization_balances WHERE node_id=? AND authorization_id=?`,
	`SELECT h.reserved_bytes,h.state,u.used_bytes FROM authorization_usage_holds h LEFT JOIN usage_reservations u ON u.node_id=h.node_id AND u.batch_id=h.batch_id WHERE h.node_id=? AND h.authorization_id=?`,
	`SELECT initial_bytes FROM authorization_source_owners WHERE node_id=? AND source_id=?`,
	`SELECT initial_bytes,remaining_bytes FROM authorization_balances WHERE node_id=? AND source_id=?`,
	`SELECT h.reserved_bytes,h.state,u.used_bytes FROM authorization_usage_holds h LEFT JOIN usage_reservations u ON u.node_id=h.node_id AND u.batch_id=h.batch_id WHERE h.node_id=? AND h.source_id=?`,
	`SELECT a.authorization_id,a.parent_authorization_id,a.boot_id,a.billing_snapshot_id,a.rule_id,a.rule_revision,a.path_generation,a.signer_epoch,a.hard_deadline,a.issuer_id FROM authorization_source_owners o JOIN authorization_records a ON a.node_id=o.node_id AND a.authorization_id=o.authorization_id WHERE o.node_id=? AND o.source_id=?`,
	`SELECT COUNT(*) FROM runtime_sessions WHERE node_id=? AND source_id=? AND state='open'`,
	`INSERT INTO runtime_sessions(node_id,session_id,boot_id,flow_key,source_id,grant_id,runtime_lease_id,share_lease_id,initial_grant_id,initial_runtime_lease_id,initial_share_lease_id,state) VALUES(?,?,?,?,?,?,?,?,?,?,?, 'open')`,
	`SELECT tokens,last_tick,boot_id FROM runtime_rate_buckets WHERE node_id=? AND source_id=?`,
	`INSERT INTO runtime_rate_buckets(node_id,source_id,boot_id,tokens,last_tick) VALUES(?,?,?,?,?) ON CONFLICT(node_id,source_id) DO UPDATE SET boot_id=excluded.boot_id,tokens=excluded.tokens,last_tick=excluded.last_tick`,
	`SELECT a.authorization_id,a.issued_at,a.kind,COALESCE(b.remaining_bytes,'') FROM authorization_records a LEFT JOIN authorization_balances b ON b.node_id=a.node_id AND b.authorization_id=a.authorization_id WHERE a.node_id=? AND a.boot_id=? AND a.rule_id=? AND a.rule_revision=? AND a.path_generation=? AND a.state='active' AND unixepoch(a.expires_at)>=unixepoch(?)`,
	`SELECT remaining_bytes FROM authorization_balances WHERE node_id=? AND authorization_id=?`,
	`SELECT boot_id,flow_key,source_id,state,grant_id,runtime_lease_id,share_lease_id,initial_grant_id,initial_runtime_lease_id,initial_share_lease_id FROM runtime_sessions WHERE node_id=? AND session_id=?`,
	`SELECT h.authorization_id,b.session_id,b.direction FROM authorization_usage_holds h LEFT JOIN runtime_funding_blocks b ON b.node_id=h.node_id AND b.batch_id=h.batch_id WHERE h.node_id=? AND h.batch_id=?`,
	`SELECT minimum_bytes,preferred_bytes,allocated_bytes,idle_digest FROM runtime_funding_requests WHERE node_id=? AND batch_id=?`,
	`SELECT session_id FROM runtime_funding_blocks WHERE node_id=? AND batch_id=?`,
	`SELECT COUNT(*),COALESCE(SUM(CASE WHEN b.session_id=? AND b.direction=? THEN 1 ELSE 0 END),0) FROM runtime_funding_blocks b JOIN usage_reservations u ON u.node_id=b.node_id AND u.batch_id=b.batch_id WHERE b.node_id=? AND u.state='reserved'`,
	`UPDATE runtime_sessions SET grant_id=?,runtime_lease_id=?,share_lease_id=? WHERE node_id=? AND session_id=? AND state='open'`,
	`INSERT INTO runtime_funding_blocks(node_id,batch_id,session_id,direction) VALUES(?,?,?,?)`,
	`INSERT INTO runtime_funding_requests(node_id,batch_id,minimum_bytes,preferred_bytes,allocated_bytes,idle_digest) VALUES(?,?,?,?,?,?)`,
	`SELECT u.boot_id,u.snapshot_id,u.flow_key,u.rule_id,u.direction,u.reserved_bytes,u.state,h.authorization_id,h.reserved_bytes,h.state,b.session_id,s.boot_id,s.flow_key,s.source_id,s.state,s.grant_id,s.runtime_lease_id,s.share_lease_id FROM runtime_funding_blocks b JOIN usage_reservations u ON u.node_id=b.node_id AND u.batch_id=b.batch_id JOIN authorization_usage_holds h ON h.node_id=u.node_id AND h.batch_id=u.batch_id JOIN runtime_sessions s ON s.node_id=b.node_id AND s.session_id=b.session_id WHERE b.node_id=? AND b.batch_id=?`,
	`SELECT block_id,prior_reserved FROM runtime_block_checkpoints WHERE node_id=? AND batch_id=?`,
	`SELECT u.boot_id,u.snapshot_id,u.flow_key,u.rule_id,u.direction,u.reserved_bytes,u.state,h.authorization_id,h.source_id,h.reserved_bytes,h.state FROM runtime_funding_blocks b JOIN usage_reservations u ON u.node_id=b.node_id AND u.batch_id=b.batch_id JOIN authorization_usage_holds h ON h.node_id=u.node_id AND h.batch_id=u.batch_id WHERE b.node_id=? AND b.batch_id=?`,
	`UPDATE usage_reservations SET reserved_bytes=?,state=?,updated_at=? WHERE node_id=? AND batch_id=?`,
	`UPDATE authorization_usage_holds SET reserved_bytes=?,state=? WHERE node_id=? AND batch_id=?`,
	`INSERT INTO runtime_block_checkpoints(node_id,batch_id,block_id,prior_reserved) VALUES(?,?,?,?)`,
	`SELECT boot_id,snapshot_id,flow_key,rule_id,direction,reserved_bytes,state,used_bytes FROM usage_reservations WHERE node_id=? AND batch_id=?`,
	`SELECT authorization_id FROM authorization_usage_holds WHERE node_id=? AND batch_id=?`,
	`SELECT payload FROM unknown_usage_batches WHERE node_id=? AND batch_id=?`,
	`SELECT payload,payload_sha256,unknown_upper_bound FROM usage_batches WHERE node_id=? AND batch_id=?`,
	`SELECT reserved_bytes,state FROM authorization_usage_holds WHERE node_id=? AND batch_id=?`,
	`SELECT source_id,authorization_id FROM authorization_usage_holds WHERE node_id=? AND batch_id=?`,
	`SELECT remaining_bytes FROM authorization_balances WHERE node_id=? AND authorization_id=? AND source_id=?`,
	`SELECT initial_bytes FROM authorization_balances WHERE node_id=? AND authorization_id=?`,
	`UPDATE authorization_balances SET remaining_bytes=?,updated_at=? WHERE node_id=? AND authorization_id=?`,
	`UPDATE authorization_usage_holds SET state=? WHERE node_id=? AND batch_id=? AND state='reserved'`,
	`INSERT INTO usage_batches(node_id,batch_id,boot_id,snapshot_id,payload,payload_sha256,unknown_upper_bound,state,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)`,
	`UPDATE usage_reservations SET state=?,used_bytes=?,updated_at=? WHERE node_id=? AND batch_id=? AND state='reserved'`,
}
